use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH, Duration};
use hmac::{Hmac, Mac};
use sha2::Sha256;
use hex;

type HmacSha256 = Hmac<Sha256>;

const SIGNATURE_VALIDITY_WINDOW: u64 = 300; // 5 minutes
const MAX_NONCE_CACHE_SIZE: usize = 10000;

#[derive(Clone)]
pub struct AuthState {
    shared_secret: Vec<u8>,
    nonce_cache: Arc<Mutex<NonceCache>>,
}

pub struct NonceCache {
    seen: HashMap<String, u64>,
    eviction_threshold: u64,
}

impl NonceCache {
    pub fn new() -> Self {
        NonceCache {
            seen: HashMap::new(),
            eviction_threshold: 0,
        }
    }

    /// Evicts entries older than the validity window to prevent unbounded growth
    pub fn evict_stale(&mut self, current_time: u64) {
        let cutoff = current_time.saturating_sub(SIGNATURE_VALIDITY_WINDOW);
        if cutoff > self.eviction_threshold {
            self.seen.retain(|_, &mut ts| ts >= cutoff);
            self.eviction_threshold = cutoff;
        }
    }

    /// Returns true if nonce was already seen (replay detected)
    pub fn check_and_insert(&mut self, nonce: &str, timestamp: u64) -> bool {
        self.evict_stale(timestamp);
        if self.seen.len() >= MAX_NONCE_CACHE_SIZE {
            // Under pressure, force eviction with tighter window
            let tight_cutoff = timestamp.saturating_sub(SIGNATURE_VALIDITY_WINDOW / 2);
            self.seen.retain(|_, &mut ts| ts >= tight_cutoff);
        }
        if self.seen.contains_key(nonce) {
            return true; // replay
        }
        self.seen.insert(nonce.to_string(), timestamp);
        false
    }
}

#[derive(Debug)]
pub struct ServiceRequest {
    pub service_id: String,
    pub timestamp: String,
    pub nonce: String,
    pub signature: String,
    pub body: String,
    pub path: String,
}

impl AuthState {
    pub fn new(secret: &[u8]) -> Self {
        AuthState {
            shared_secret: secret.to_vec(),
            nonce_cache: Arc::new(Mutex::new(NonceCache::new())),
        }
    }

    pub fn compute_signature(&self, service_id: &str, timestamp: &str, nonce: &str, path: &str, body: &str) -> String {
        let mut mac = HmacSha256::new_from_slice(&self.shared_secret)
            .expect("HMAC key length error");
        // Canonical signing format: service|timestamp|nonce|path|body
        let message = format!("{}|{}|{}|{}|{}", service_id, timestamp, nonce, path, body);
        mac.update(message.as_bytes());
        hex::encode(mac.finalize().into_bytes())
    }

    pub fn verify_request(&self, req: &ServiceRequest) -> Result<(), AuthError> {
        // Step 1: Parse and validate timestamp
        let ts: u64 = req.timestamp.parse()
            .map_err(|_| AuthError::InvalidTimestamp)?;

        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let drift = if now > ts { now - ts } else { ts - now };
        if drift > SIGNATURE_VALIDITY_WINDOW {
            return Err(AuthError::ExpiredSignature);
        }

        // Step 2: Verify HMAC signature
        let expected = self.compute_signature(
            &req.service_id,
            &req.timestamp,
            &req.nonce,
            &req.path,
            &req.body,
        );

        if !constant_time_eq(expected.as_bytes(), req.signature.as_bytes()) {
            return Err(AuthError::InvalidSignature);
        }

        // Step 3: Check nonce for replay
        let mut cache = self.nonce_cache.lock().unwrap();
        if cache.check_and_insert(&req.nonce, ts) {
            return Err(AuthError::ReplayDetected);
        }

        Ok(())
    }
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    a.iter().zip(b.iter()).fold(0u8, |acc, (x, y)| acc | (x ^ y)) == 0
}

#[derive(Debug)]
pub enum AuthError {
    InvalidTimestamp,
    ExpiredSignature,
    InvalidSignature,
    ReplayDetected,
}

/// Handler for incoming cross-service requests
pub fn handle_service_request(state: &AuthState, req: ServiceRequest) -> Result<String, AuthError> {
    state.verify_request(&req)?;
    Ok(format!("Authenticated request from {} to {}", req.service_id, req.path))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_request() {
        let state = AuthState::new(b"supersecretkey123");
        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();
        let ts = now.to_string();
        let nonce = "unique-nonce-abc123";
        let path = "/api/data";
        let body = "{\"key\": \"value\"}";
        let sig = state.compute_signature("service-a", &ts, nonce, path, body);

        let req = ServiceRequest {
            service_id: "service-a".to_string(),
            timestamp: ts,
            nonce: nonce.to_string(),
            signature: sig,
            body: body.to_string(),
            path: path.to_string(),
        };

        assert!(handle_service_request(&state, req).is_ok());
    }

    #[test]
    fn test_replay_detected() {
        let state = AuthState::new(b"supersecretkey123");
        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();
        let ts = now.to_string();
        let nonce = "same-nonce";
        let path = "/api/data";
        let body = "hello";
        let sig = state.compute_signature("service-a", &ts, nonce, path, body);

        let req1 = ServiceRequest {
            service_id: "service-a".to_string(),
            timestamp: ts.clone(),
            nonce: nonce.to_string(),
            signature: sig.clone(),
            body: body.to_string(),
            path: path.to_string(),
        };
        let req2 = ServiceRequest {
            service_id: "service-a".to_string(),
            timestamp: ts,
            nonce: nonce.to_string(),
            signature: sig,
            body: body.to_string(),
            path: path.to_string(),
        };

        assert!(handle_service_request(&state, req1).is_ok());
        assert!(matches!(handle_service_request(&state, req2), Err(AuthError::ReplayDetected)));
    }
}
